mapper.select:
/* LeavePromotionMapper.selectNextPromoId */
SELECT CONCAT('LP', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'LEAVE_PROMOTION_ID'))
  FROM DUAL

mapper.insert:
/* LeavePromotionMapper.insertPromotionLog */
INSERT INTO TB_LEAVE_PROMOTION_LOG (
      PROMO_ID
    , CMPNY_CD
    , SITE_CD
    , USER_CD
    , BASE_GRANT_ID
    , BASE_AVAIL_TO_DATE
    , PROMO_STAGE
    , NOTICED_DATE
    , STAGE1_DESIGNATED_DAYS
    , STAGE2_TARGET_DAYS
    , STAGE2_DESIGNATED_DATE
    , STATUS
    , LOGIN_NOTIFIED_YN
    , DEDUP_KEY
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{promoId}
    , #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{baseGrantId}
    , #{baseAvailToDate}
    , #{promoStage}
    , #{noticedDate}
    , IFNULL(#{stage1DesignatedDays}, 0.0)
    , IFNULL(#{stage2TargetDays}, 0.0)
    , #{stage2DesignatedDate}
    , #{status}
    , 'N'
    , #{dedupKey}
    , 'N'
    , #{insertNo}
    , NOW()
)

mapper.select:
/* LeavePromotionMapper.countByDedupKey */
SELECT COUNT(1)
  FROM TB_LEAVE_PROMOTION_LOG
 WHERE CMPNY_CD  = #{cmpnyCd}
   AND DEDUP_KEY = #{dedupKey}
   AND DEL_YN    = 'N'

mapper.insert:
/* LeavePromotionMapper.insertPromotionLeaveUse */
INSERT INTO TB_USER_LEAVE_USE (
      LEAVE_ID
    , CMPNY_CD
    , SITE_CD
    , USER_CD
    , LEAVE_CD
    , REQ_ID
    , GRANT_ID
    , START_DATE
    , END_DATE
    , USE_UNIT_TYPE
    , LEAVE_DAYS
    , LEAVE_REASON
    , LEAVE_STATUS
    , PROMOTION_STAGE
    , DESIGNATOR_TYPE
    , ORIG_DESIGNATED_DATE
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{leaveId}
    , #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{leaveCd}
    , NULL
    , #{grantId}
    , #{startDate}
    , #{endDate}
    , #{useUnitType}
    , #{leaveDays}
    , #{leaveReason}
    , #{leaveStatus}
    , #{promotionStage}
    , #{designatorType}
    , #{origDesignatedDate}
    , 'N'
    , #{insertNo}
    , NOW()
)

mapper.update:
/* LeavePromotionMapper.addStage1DesignatedDays */
UPDATE TB_LEAVE_PROMOTION_LOG
   SET STAGE1_DESIGNATED_DAYS = STAGE1_DESIGNATED_DAYS + #{addDays}
     , UPDATE_NO   = #{operatorNo}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD    = #{cmpnyCd}
   AND DEDUP_KEY   = #{dedupKey}
   AND PROMO_STAGE = 'FIRST'
   AND DEL_YN      = 'N'

/* LeavePromotionMapper.markStage2Designated */
UPDATE TB_LEAVE_PROMOTION_LOG
   SET STATUS                 = 'DESIGNATED'
     , STAGE2_DESIGNATED_DATE = #{designatedDate}
     , UPDATE_NO   = #{operatorNo}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD    = #{cmpnyCd}
   AND DEDUP_KEY   = #{dedupKey}
   AND PROMO_STAGE = 'SECOND'
   AND DEL_YN      = 'N'

mapper.select:
/* LeavePromotionMapper.selectMyPromotionLeaveDates */
SELECT LU.START_DATE
  FROM TB_USER_LEAVE_USE LU
 WHERE LU.CMPNY_CD        = #{cmpnyCd}
   AND LU.USER_CD         = #{userCd}
   AND LU.LEAVE_CD        = 'SYS_ANNUAL'
   AND LU.LEAVE_STATUS    = 'CONFIRMED'
   AND LU.DEL_YN          = 'N'
   AND LU.PROMOTION_STAGE IN ('FIRST', 'SECOND')
 ORDER BY LU.START_DATE ASC

mapper.update:
/* LeavePromotionMapper.markLoginNotified */
UPDATE TB_LEAVE_PROMOTION_LOG
   SET LOGIN_NOTIFIED_YN = 'Y'
     , UPDATE_NO   = #{operatorNo}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD    = #{cmpnyCd}
   AND USER_CD     = #{userCd}
   AND PROMO_STAGE = 'FIRST'
   AND STATUS IN ('NOTICED', 'COMPLETED')
   AND DEL_YN      = 'N'

mapper.select:
/* LeavePromotionMapper.countWorkPlanDay */
SELECT COUNT(1)
  FROM TB_USER_WORK_PLAN WP
 WHERE WP.CMPNY_CD = #{cmpnyCd}
   AND WP.SITE_CD  = #{siteCd}
   AND WP.USER_CD  = #{userCd}
   AND WP.WORK_YMD = #{workYmd}

/* LeavePromotionMapper.countAttendanceOn */
SELECT COUNT(1)
  FROM TB_USER_ATTD_MGMT A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.SITE_CD  = #{siteCd}
   AND A.USER_CD  = #{userCd}
   AND A.WORK_YMD = #{workYmd}
   AND A.DEL_YN   = 'N'
